/* saero.org: the split maths and the advice rule, run in the visitor's browser. No page code in here (nothing
   touches the DOM), so it can also be loaded and tested on its own.
     planner()  = the split maths.
     advise()   = the advice for each lock (move now or stay, the split, the tap-to-open breakdown, Coming up). It
                  keeps no memory of earlier visits: each visit works the advice out fresh from the latest data. */
(function (root) {
  "use strict";

  // ======================= the split maths =======================
  // crowding: square root unless the data carries another model (pools.json crowd)
  function incAgeH(p, at) {
    let newest = null;
    for (const g of p.progs || []) if (!g.upcoming && g.start <= at && at < g.end && (g.usd || 0) >= 25) newest = Math.max(newest ?? -Infinity, g.start);
    return newest == null ? null : (at - newest) / 3600;
  }
  function crowdBetaOf(spec, at) {
    if (spec?.kind === "beta" && spec.b > 0) return () => spec.b;
    if (spec?.kind === "age" && spec.a > 0 && spec.c > 0) return (p) => { const h = p.age !== undefined ? p.age : incAgeH(p, at); return h != null && h < 6 ? spec.a : h != null && h < 24 ? spec.c : 0.5; };
    return null;
  }
  // k = estimate scale (default 1): every pool's pay x k; crowding reads R/W/Y, so splits are unchanged and $ figures are x k
  // network fees for one move, paid in ETH and never refunded: a few cents of gas per transaction on Base, and on every
  // other network the gas the root voter buys there x its fixed price per gas (measured 11-01 on 448 messages, refit
  // 11-07). Same as the server's fee model:
  // A network the lock STAYS on (11-07, review item 8: it was charged a full exit + entry, so good moves were blocked): Aero
  // sends it one message with the new pools, not an exit and an entry. Refit 11-07 on 221 real messages of 11-01..11-07
  // on 35 same-network changes the old exit + entry sum was 2x the gas really bought (median
  // 0.51x). Such a change buys 0.50M gas + 0.50M per pool it ends up in + 0.37M per pool it leaves there, plus the network's
  // allocation message (0.32M) when its total goes up or the ~0.00014 ETH return fee when it goes down (unknown: the dearer);
  // nothing at all when pools and amounts there stay the same. The return fee is paid per network that gives sAERO back
  // (two-network exits paid 1.88x), so every "out" carries it (until 11-07: once per move).
  // from / to = one entry per pool: a network name ("base", "ethereum", ...) or { c, x, pool } (network, sAERO, pool id);
  // without amounts / pool ids a same-network change is costed as if every pool there changed.
  // Elysium (network 99901, added 11-09): measured the same day on its first 13 direct allocation transactions (11 entries,
  // 2 exits; Ethereum 0.75 / Robinhood 0.375 / Optimism 0.187 / Arbitrum 0.169 re-read in the same run as the control):
  // 0.3747 gwei per gas on every message, the Robinhood / Ink / Arc price, and
  // the gas bought fits the model (entering 1 pool 1.43M vs 1.44M, 3 pools 2.33M vs 2.36M, 4 pools 2.68M vs 2.82M;
  // leaving 1 pool 0.92M vs 0.97M, 4 pools 2.17M vs 2.32M). A network missing from `gwei` is charged Ethereum's, the dearest.
  const NET_FEE = { gwei: { ethereum: 0.75, robinhood: 0.375, ink: 0.375, arc: 0.375, elysium: 0.375, optimism: 0.187, arbitrum: 0.169 },
    enter: [0.98e6, 0.46e6], exit: [0.52e6, 0.45e6], change: [0.5e6, 0.5e6, 0.37e6], chain: 0.32e6, exitEth: 0.00014, txUsd: 0.05 };
  function moveFee(from, to, eth) {
    if (!(eth > 0)) return null;
    const r2 = (x) => Math.round(x * 100) / 100, parts = [];
    // per network: pool count, sAERO (when every entry carries it) and pool -> sAERO (when every entry names its pool)
    const group = (l) => {
      const m = new Map();
      for (const e of l || []) {
        const o = e && typeof e === "object" ? e : null, net = o ? o.c : e;
        if (!net || net === "base") continue;
        const g = m.get(net) || m.set(net, { n: 0, x: 0, sized: true, pools: new Map() }).get(net);
        g.n++;
        if (o && o.x >= 0) g.x += o.x; else g.sized = false;
        if (o && o.pool) g.pools.set(o.pool, (g.pools.get(o.pool) || 0) + (o.x || 0));
      }
      return m;
    };
    const F = group(from), T = group(to);
    const usdGas = (gas, net) => gas * (NET_FEE.gwei[net] ?? NET_FEE.gwei.ethereum) * 1e-9 * eth, back = NET_FEE.exitEth * eth;
    for (const [net, f] of F) if (!T.has(net)) parts.push({ net, kind: "out", usd: r2(usdGas(NET_FEE.exit[0] + NET_FEE.exit[1] * f.n, net) + back) });
    for (const [net, t] of T) {
      const f = F.get(net);
      if (!f) { parts.push({ net, kind: "in", usd: r2(usdGas(NET_FEE.enter[0] + NET_FEE.enter[1] * t.n, net)) }); continue; }
      const named = f.pools.size > 0 && t.pools.size > 0 && f.n === [...f.pools.keys()].length && t.n === [...t.pools.keys()].length;
      const dropped = named ? [...f.pools.keys()].filter((p) => !t.pools.has(p)).length : f.n;
      const sized = f.sized && t.sized, near = (a, b) => Math.abs(a - b) <= 0.005 * Math.max(a, b, 1e-9), level = sized && near(f.x, t.x);
      if (named && level && f.pools.size === t.pools.size && [...t.pools].every(([p, x]) => f.pools.has(p) && near(f.pools.get(p), x))) continue;   // nothing changes there
      const [a, b, c] = NET_FEE.change, up = usdGas(NET_FEE.chain, net);
      parts.push({ net, kind: "change", usd: r2(usdGas(a + b * t.n + c * dropped, net) + (!sized ? Math.max(up, back) : level ? 0 : t.x > f.x ? up : back)) });
    }
    return { usd: r2(NET_FEE.txUsd * ((from || []).length ? 2 : 1) + parts.reduce((t, p) => t + p.usd, 0)), parts };
  }
  // moveFee entries from a lock's allocations (less the kept ones) and from a split ([{ p, x }] or advice rows { chain, sAERO, pool })
  const feeFrom = (s, kept = []) => (s.allocs || []).filter((a) => !kept.includes(a)).map((a) => ({ c: String(a.pool).split(":")[0], x: a.weight, pool: a.pool }));
  const feeTo = (split) => (split || []).map((c) => (c.p ? { c: c.p.c, x: c.x, pool: c.p.id } : { c: c.chain, x: c.sAERO ?? c.x, pool: c.pool }));

  // The advice's pick of networks (11-04: "suggest the best pools ... that takes into account the cost of fees vs the
  // rewards over 47 hours"). planOf(drop, keep) plans a lock with the networks in `drop` left out and its sAERO on the
  // networks in `keep` (a part of drop) left where it is, and returns { o, net }: net = the extra over the 47 h hold
  // after network fees. Every mix of the networks in play (the ones the best split uses and the ones the lock is on now;
  // Base is always allowed) is tried; a mix that brings in a new network adds it to play (3 rounds at most, 6 networks).
  // The mix that nets the most wins; with every network allowed first, so a tie keeps it.
  // `ok(x)` (11-07): the move tests (3% and $0.25/day better, fees covered). The best-netting mix that passes them wins
  // over one that nets more but fails them; none passes: as before.
  function netMix(planOf, curNets, ok = null) {
    let C = planOf([], []), G = ok && C.o.split.length && ok(C) ? C : null;
    const play = [], tried = new Set(["|"]);
    const subsets = (L) => Array.from({ length: 1 << L.length }, (_, m) => L.filter((_, i) => m & (1 << i)));
    for (let round = 0; round < 3; round++) {
      const add = [...new Set([...C.o.split.map((c) => c.p.c), ...curNets])].filter((n) => n !== "base" && !play.includes(n));
      if (!add.length || play.length >= 6) break;
      play.push(...add.slice(0, 6 - play.length));
      for (const drop of subsets(play)) for (const keep of subsets(drop.filter((n) => curNets.includes(n)))) {
        const k = `${drop.join(",")}|${keep.join(",")}`; if (tried.has(k)) continue; tried.add(k);
        const x = planOf(drop, keep);
        if (!x.o.split.length) continue;
        if (x.net > C.net + 1e-9) C = x;
        if (ok && (!G || x.net > G.net + 1e-9) && ok(x)) G = x;
      }
    }
    return G || C;
  }

  function planner(sum, { adj, beta, betaOf = null, k = 1 } = {}) {
    if (!betaOf && beta == null) betaOf = crowdBetaOf(sum.crowd, sum.at);
    if (beta == null) beta = 0.5;
    if (!(k > 0 && Number.isFinite(k))) k = 1;
    const R =(p) => k * ((p.fe ?? p.f96 ?? 0) + (p.ih || 0) + (adj ? adj.get(p.id) || 0 : 0));   // fe = f96 x time-of-week factor
    // the market's pay per sAERO across every pool of 100k+ (all networks)
    const bigPools = sum.pools.filter((p) => p.W >= 100000);
    const Y = bigPools.reduce((t, p) => t + R(p), 0) / Math.max(1, bigPools.reduce((t, p) => t + p.W, 0));
    // expected weight during the hold: pools paying far above the market draw more sAERO (square-root fit)
    const crowd = (v, p) => { const b = betaOf ? betaOf(p) : beta; return b === 0.5 ? Math.sqrt(v) : Math.pow(v, b); };   // the advice shows its figures with betaOf
    const wHold = (p, mine) => { const W = Math.max(1, p.W - (mine || 0)); return W * crowd(Math.max(1, R(p) / W / Y), p); };

    // Most income for X sAERO: equalise the marginal rate R*W/(W+x)^2 across pools (water-filling).
    function bestSplit(pools, X, mine) {
      const cand = pools.filter((p) => R(p) > 0).map((p) => ({ p, W: wHold(p, mine.get(p.id)) }));
      if (!cand.length || X <= 0) return [];
      const alloc = (lam) => cand.map((c) => ({ ...c, x: Math.sqrt((R(c.p) * c.W) / lam) - c.W })).filter((c) => c.x > 0);
      let lo = 1e-14, hi = Math.max(...cand.map((c) => R(c.p) / c.W));
      for (let i = 0; i < 200; i++) { const mid = Math.sqrt(lo * hi); const s = alloc(mid).reduce((a, c) => a + c.x, 0); if (s > X) lo = mid; else hi = mid; }
      const a = alloc(hi); const s = a.reduce((t, c) => t + c.x, 0);
      return a.map((c) => ({ ...c, x: (c.x * X) / s })).sort((u, v) => v.x - u.x);
    }

    const byId = new Map(sum.pools.map((p) => [p.id, p]));
    // what one allocation earns per day at today's pool rates (its own weight is already in the pool)
    const allocPay = (a) => { const p = byId.get(a.pool); return p ? (R(p) * a.weight) / Math.max(p.W, a.weight) : 0; };
    const stakePay = (s) => (s.allocs || []).reduce((t, a) => t + allocPay(a), 0);

    // pools the advice picks from: 100k+ sAERO, or any of 1k+ with live incentives; every network unless baseOnly
    // or `nets` (the networks the visitor wants suggestions on)
    // `drop` = networks left out (the advice's fee-aware search)
    function poolsFor({ minSize = 100000, baseOnly = false, nets = null, extra = null, drop = null } = {}) {
      let pools = sum.pools.filter((p) => !p.no && (p.W >= minSize || (p.ih > 0 && p.W >= 1000) || (extra && extra.has(p.id))));   // no = never suggested (set with the pool data)
      if (baseOnly) pools = pools.filter((p) => p.c === "base");
      if (nets) pools = pools.filter((p) => nets.includes(p.c));
      if (drop && drop.length) pools = pools.filter((p) => !drop.includes(p.c));
      return pools;
    }

    // one lock: its best split vs where it is now, other locks held still. Small locks always get 3 pools.
    function lockOption(s, pools, maxPools = 8) {
      const own = new Map((s.allocs || []).map((a) => [a.pool, a.weight]));   // this lock leaves its pools when it moves
      const n = s.amount >= 50000 ? maxPools : 3;
      const full = bestSplit(pools, s.amount, own);
      const a = bestSplit(full.slice(0, n).map((c) => c.p), s.amount, own).filter((c) => c.x >= 0.02 * s.amount);
      const t = a.reduce((u, c) => u + c.x, 0); a.forEach((c) => (c.x = (c.x * s.amount) / t));
      const best = a.reduce((u, c) => u + (R(c.p) * c.x) / (c.W + c.x), 0);
      const now = stakePay(s);
      return { s, now, best, gain: best - now, rel: now > 0 ? best / now - 1 : Infinity,
        split: a.map((c) => ({ p: c.p, x: c.x, pay: (R(c.p) * c.x) / (c.W + c.x) })) };
    }

    // a split valued the way lockOption values a new one: this lock's own sAERO out of each pool, same crowding
    const fairPay = (p, x, own) => (x > 0 ? (R(p) * x) / (wHold(p, own || 0) + x) : 0);
    // what the lock should earn per day over the next 47 h if it STAYS where it is, valued like a move
    const stakeFair = (s) => (s.allocs || []).reduce((t, a) => { const p = byId.get(a.pool); return t + (p ? fairPay(p, a.weight, a.weight) : 0); }, 0);
    function splitValue(s, split) {
      const own = new Map((s.allocs || []).map((a) => [a.pool, a.weight]));
      return split.map((c) => { const p = byId.get(c.pool); return { pool: c.pool, x: c.x, pay: p ? fairPay(p, c.x, own.get(c.pool)) : 0 }; });
    }

    // The advice's plan for one lock. With baseOnly, sAERO on other networks stays where it is and the split covers
    // the Base part (sB); with `nets`, the same for sAERO on networks outside that list. A big lock gets the split for each pool count in `ns` and uses the fewest pools that earn
    // within `slack` $/day or `pct` of the most, whichever is more.
    // `keep` = networks whose sAERO stays where it is too (no fee to leave)
    function advisedOption(s, pools, { ns = [5, 8, 12, 16, 20], slack = 0.25, baseOnly = false, nets = null, keep = null, big = 50000, small = 8, pct = 0 } = {}) {
      const net = (a) => String(a.pool).split(":")[0];
      const kept = (s.allocs || []).filter((a) => (baseOnly ? net(a) !== "base" : nets ? !nets.includes(net(a)) : false) || (keep && keep.includes(net(a))));
      const keptAmt = kept.reduce((t, a) => t + a.weight, 0);
      const sB = kept.length ? { ...s, amount: Math.max(0, s.amount - keptAmt), allocs: (s.allocs || []).filter((a) => !kept.includes(a)) } : s;
      // the pool counts follow the part that moves (11-07: a big lock with under 50k left to move got a 3-pool split
      // labelled "5 pools"); a part under 50k gets lockOption's 3 pools, labelled 3
      const many = sB.amount >= big && sB.amount >= 50000;
      const opts = (many ? ns : [small]).map((n) => ({ n: sB.amount >= 50000 ? n : Math.min(n, 3), o: lockOption(sB, pools, n) }));
      const most = Math.max(...opts.map((x) => x.o.best));
      const allow = Math.max(slack, pct * most);   // 11-06: 1% of the best, at least $0.25 a day ("a lot of pools for little gain")
      const pick = opts.find((x) => most - x.o.best <= allow) || opts[opts.length - 1];
      return { sB, kept, keptAmt, opts, n: pick.n, o: pick.o, slack: allow };
    }

    return { R, Y, wHold, bestSplit, byId, allocPay, stakePay, poolsFor, lockOption, stakeFair, splitValue, advisedOption, sum, beta, k };
  }

  // ======================= the advice (no memory of earlier visits) =======================
  const H = 3600, HOLD = 47 * H, BIG = 50000;
  // the advice's estimate scale for a lock (pools.json estK, from the track record): 1 when missing
  const estKOf = (sum, amt) => { const e = sum && sum.estK, v = e ? (amt >= BIG ? e.big : e.small) : null; return v > 0 && Number.isFinite(v) ? v : 1; };
  // the gain over staying as shown, x g (pools.json estK.gBig / gSmall: what moves really paid vs the gain shown, on the
  // median day lately); 1 when missing. Display only: Move / Stay is decided on the raw figures.
  const gainKOf = () => 1;   // 11-09 (trust the forecast): the whole forecast gain counts
  const PLAN = { maxPools: 8, minSize: 100000, baseOnly: false };   // the plan settings: every network
  const POLICY = { moveRel: 0.03, moveMin: 0.25, together: H, preview: 6 * H,
    poolsN: [5, 8, 12, 16, 20],   // big locks: the split is worked out for each of these pool counts (20 = most Aero allows)
    poolsSlack: 0.25,             // ...and the advice uses the fewest pools that earn within $0.25/day of the most
    poolsPct: 0.01 };             // ...or within 1% of the most when that is more (11-06: "Yes, use 1%")

  // stock tokens
  const TICK = new Set("AAPL AMZN AMD ARM AVGO BE BIDU BILI BRK.B BUD CRWV DUOL GME GOOGL HIMS HSAI INFY LI LLY MRNA MSFT MSTR MU NFLX NIO NOK NVDA NVO ORCL PDD PFE PLTR QUBT RBLX SAN SAP SE SKHY SNDK SONY SPCX TSLA TTWO UBER UL VALE WRD META COIN CRCL GLD INTC SNAP DJT GLXY LULU NET NU RDDT SPY WEN".split(" "));
  function isStockSym(s) {
    if (!s) return false;
    if (/^wt[A-Z]{2,6}$/.test(s)) return true;                         // WisdomTree wtCOIN / wtSPYM / wtSGOV
    if (/^[A-Z][A-Z.]{0,5}c$/.test(s)) return true;                    // the "c" series: NVDAc, ARMc, BRK.Bc
    return TICK.has(s);
  }

  // ---------- formatting (US Eastern, am/pm) ----------
  const ET = "America/New_York";
  const fT = new Intl.DateTimeFormat("en-US", { timeZone: ET, hour: "numeric", minute: "2-digit" });
  const fD = new Intl.DateTimeFormat("en-US", { timeZone: ET, year: "numeric", month: "numeric", day: "numeric" });
  const fW = new Intl.DateTimeFormat("en-US", { timeZone: ET, weekday: "short" });
  const fM = new Intl.DateTimeFormat("en-US", { timeZone: ET, month: "short", day: "numeric" });
  const tm = (t) => fT.format(new Date(t * 1000)).replace(" AM", " am").replace(" PM", " pm");
  // same day: "9:33 pm"; within 6 days: "Mon 9:33 pm"; further: "Mon Nov 2, 9:33 pm"
  function when(t, now) {
    if (fD.format(new Date(t * 1000)) === fD.format(new Date(now * 1000))) return tm(t);
    const d = new Date(t * 1000);
    return Math.abs(t - now) < 6 * 86400 ? `${fW.format(d)} ${tm(t)}` : `${fW.format(d)} ${fM.format(d)}, ${tm(t)}`;
  }
  const usd = (v) => (Math.abs(v) >= 9.995 ? "$" + Math.round(v).toLocaleString("en-US") : "$" + Math.max(0, v).toFixed(2));
  const r2 = (x) => Math.round(x * 100) / 100, r1 = (x) => Math.round(x * 10) / 10;
  const pctTxt = (x) => `${Math.round(x * 100)}%`;
  const list = (a) => (a.length <= 1 ? a.join("") : a.slice(0, -1).join(", ") + " and " + a[a.length - 1]);
  const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);

  function namer(sum) {
    const count = new Map(); for (const p of sum.pools) count.set(p.n, (count.get(p.n) || 0) + 1);
    return (p) => (p ? (count.get(p.n) > 1 ? `${p.n} ${p.k}` : p.n) : "?");
  }
  // whole percents that add up to `want` (100, or less when part of the lock stays on another network)
  function wholePct(xs, total, want = 100) {
    const raw = xs.map((x) => (x / total) * 100), pct = raw.map(Math.floor);
    raw.map((r, j) => [r - pct[j], j]).sort((u, v) => v[0] - u[0]).slice(0, Math.max(0, want - pct.reduce((u, v) => u + v, 0))).forEach(([, j]) => pct[j]++);
    return pct;
  }
  // a pool whose own team holds locks that could swamp it (pool.tm: the team scan on the data side). Same text in the server advice.
  const teamTag = (p) => { const m = (x) => (x >= 1e6 ? (x / 1e6).toFixed(1) + "M" : Math.round(x / 1e3) + "k"); return `the team behind this pool holds ${m(p.tm.s)} sAERO and can pile in at any time (${m(p.W)} sAERO vote here now)`; };
  function splitOut(P, name, s, rows, pct, apr) {
    return rows.map((c, j) => { const p = P.byId.get(c.pool); return { pool: c.pool, name: name(p), pair: p?.n || "?", kind: p?.k || "", chain: p?.c || "", pct: pct[j], sAERO: Math.round(c.x), usdPerDay: r2(c.pay), aprPct: r1(apr(c.pay, c.x)), ...(p?.tm ? { team: teamTag(p) } : {}) }; })
      .sort((a, b) => b.pct - a.pct || b.usdPerDay - a.usdPerDay);
  }
  // how much of a split's pay is incentives, and the end time that carries most of it
  function endingOf(P, rows, now) {
    let tot = 0, inc = 0; const ends = new Map();
    for (const c of rows) {
      const p = P.byId.get(c.pool); if (!p) continue;
      const R = P.R(p); if (!(R > 0)) continue;
      tot += c.pay;
      const ip = (c.pay * (p.ih || 0) * (P.k || 1)) / R; inc += ip;   // R and pay carry k, so ih does too
      const pr = (p.progs || []).filter((g) => !g.upcoming && g.end > now), u = pr.reduce((a, g) => a + (g.usd || 0), 0);
      for (const g of pr) { const k = Math.round(g.end / 1800) * 1800; ends.set(k, (ends.get(k) || 0) + (ip * (g.usd || 0)) / Math.max(u, 1e-9)); }
    }
    if (!(tot > 0)) return null;
    const top = [...ends.entries()].sort((a, b) => b[1] - a[1])[0];
    return { incShare: r2(inc / tot), at: top ? top[0] : null, share: top ? r2(top[1] / tot) : 0 };
  }

  // The tap-to-open view of one lock: the split for each pool count, where it is now, and the logic behind each pool.
  // Every row is valued like the plan (this lock's own sAERO out of the pool, the expected crowding in).
  // `away` = sAERO on a network whose node did not answer the wallet lookup (or one this page does not know): it stays put
  // and is counted at the market's average pay per sAERO.
  function explainLock(P, s, sB, pools, opts, pickN, keptA, now, apr, away = 0) {
    const tags = (p) => {
      const R = P.R(p), inc = (p.ih || 0) * (P.k || 1), t = [];   // R carries the estimate scale k
      const pr = (p.progs || []).filter((g) => !g.upcoming && g.end > now).sort((a, b) => (b.usd || 0) - (a.usd || 0));
      if (!(inc > 0)) t.push("fees only");
      else if (inc >= 0.5 * R) t.push(pr[0] ? `mostly incentives, ending ${when(pr[0].end, now)}` : "mostly incentives");
      else if (pr[0] && pr[0].end < now + HOLD) t.push(`incentives end ${when(pr[0].end, now)}`);
      if ((p.n || "").split("/").some(isStockSym)) t.push("stock token");
      if (p.tm) t.push(teamTag(p));
      if (p.f96 > 0 && p.f24 != null && p.f24 < 0.6 * p.f96 && inc < 0.5 * R) t.push(`fees −${Math.round(100 * (1 - p.f24 / p.f96))}% vs 4-day avg`);
      if (p.f96 > 0 && p.f24 != null && p.f24 > 1.6 * p.f96 && inc < 0.5 * R) t.push(`fees +${Math.round(100 * (p.f24 / p.f96 - 1))}% vs 4-day avg`);
      return t;
    };
    const own = new Map((s.allocs || []).map((a) => [a.pool, a.weight]));
    // the logic behind one pool: what it pays its voters over the hold and from what, how many vote there now, how many
    // are expected to join, the share this lock would hold, and the rate on one more sAERO there
    const row = (p, x, pay, pc, extra) => {
      const R = P.R(p), Wx = P.wHold(p, own.get(p.id) || 0), Wo = Math.max(1, p.W - (own.get(p.id) || 0));
      const pr = (p.progs || []).filter((g) => !g.upcoming && g.end > now).sort((a, b) => (b.usd || 0) - (a.usd || 0));
      return { pool: p.id, pair: p.n, kind: p.k, chain: p.c, pct: pc, usdPerDay: r2(pay), aprPct: r1(apr(pay, x)),
        feesDay: Math.round(p.fe ?? p.f96 ?? 0), fees96: Math.round(p.f96 ?? 0), sf: p.sf ?? 1, incDay: Math.round(p.ih || 0), incNowDay: Math.round(p.inc || 0), incEnd: pr[0]?.end || null,
        poolM: r2(p.W / 1e6), othersM: r2(Wo / 1e6), expM: r2(Wx / 1e6), joinPct: Math.round(100 * (Wx / Wo - 1)),
        perVote: P.Y > 0 && p.W > 0 ? r2(R / p.W / P.Y) : null,
        rateNow: r1(apr(R, Wo)), rateExp: r1(apr(R, Wx)), sharePct: r1((100 * x) / (Wx + x)),
        // paysNow (11-13): what the pool pays its voters this moment, per sAERO: fees right now + today's incentives, over the pool as it is
        paysNow: p.W > 0 ? r1(apr((p.fn ?? p.fa24 ?? p.f24 ?? p.f96 ?? 0) + (p.inc || 0), p.W)) : null,
        margApr: r1(apr((R * Wx) / (Wx + x) ** 2, 1)), tags: tags(p), ...extra };
    };
    const awayRow = () => ({ pool: null, pair: "Other networks", kind: "", chain: "", pct: Math.round((100 * away) / s.amount), usdPerDay: r2(away * P.Y), aprPct: r1(apr(away * P.Y, away)),
      feesDay: null, incDay: null, poolM: null, perVote: null, tags: [], kept: true, away: true });
    const byPct = (u, v) => v.pct - u.pct || v.usdPerDay - u.usdPerDay;
    const keptRows = keptA.map((a) => { const p = P.byId.get(a.pool); return p ? row(p, a.weight, P.stakeFair({ allocs: [a] }), Math.round((100 * a.weight) / s.amount), { kept: true }) : null; }).filter(Boolean);
    if (away > 0) keptRows.push(awayRow());
    const keptPay = keptRows.reduce((t, r) => t + r.usdPerDay, 0);
    const basePct = Math.round((100 * sB.amount) / s.amount);
    const fromNets = feeFrom(s, keptA);   // network fees: what it leaves (with amounts and pools, moveFee)
    // the uncapped split (every pool allowed): how many pools it would really use, and the first pool left out
    const full = P.bestSplit(pools, sB.amount, own);
    const options = opts.map(({ n, o }) => {
      const pct = wholePct(o.split.map((c) => c.x), s.amount, basePct);
      const best = [...o.split.map((c, j) => row(c.p, c.x, c.pay, pct[j])), ...keptRows].sort(byPct);
      const used = new Set(o.split.map((c) => c.p.id));
      const level = o.split.length ? Math.min(...o.split.map((c) => { const W = P.wHold(c.p, own.get(c.p.id) || 0); return apr((P.R(c.p) * W) / (W + c.x) ** 2, 1); })) : null;   // the rate on one more sAERO in its pools
      // next pool: the one the cap left out, else the best-paying pool the split did not use (it starts below the level)
      const capped = full.filter((c) => c.x >= 0.02 * sB.amount).length > o.split.length;
      let nx = null;
      if (capped) nx = full.find((c) => !used.has(c.p.id) && c.x >= 0.02 * sB.amount);
      else nx = pools.filter((p) => P.R(p) > 0 && !used.has(p.id)).map((p) => ({ p, W: P.wHold(p, own.get(p.id) || 0) })).sort((u, v) => P.R(v.p) / v.W - P.R(u.p) / u.W)[0];
      // how much of this split's pay is incentives, and when they end (weighted by incentive pay, kept rows included)
      let tot = away * P.Y, inc = 0; const ends = new Map();
      for (const r of [...o.split.map((c) => ({ p: c.p, pay: c.pay })), ...keptA.map((a) => ({ p: P.byId.get(a.pool), pay: P.stakeFair({ allocs: [a] }) }))]) {
        if (!r.p) continue; const R = P.R(r.p); tot += r.pay; if (!(R > 0) || !(r.p.ih > 0)) continue;
        const ip = (r.pay * r.p.ih * (P.k || 1)) / R; inc += ip;
        const pr = (r.p.progs || []).filter((g) => !g.upcoming && g.end > now), u = pr.reduce((a, g) => a + (g.usd || 0), 0);
        for (const g of pr) { const k = Math.round(g.end / 1800) * 1800; ends.set(k, (ends.get(k) || 0) + (ip * (g.usd || 0)) / Math.max(u, 1e-9)); }
      }
      const incShare = tot > 0 ? r2(inc / tot) : 0;
      const endList = [...ends.entries()].map(([at, v]) => ({ at, share: r2(v / Math.max(tot, 1e-9)) })).filter((x) => x.share >= 0.02).sort((a, b) => b.share - a.share);
      return { n, pools: o.split.length + keptRows.length, usdPerDay: r2(o.best + keptPay), aprPct: r1(apr(o.best + keptPay, s.amount)), best, incShare, ends: endList,
        level: level == null ? null : r1(level), capped, fee: moveFee(fromNets, feeTo(o.split), P.sum.eth)?.usd ?? null,
        next: nx ? { pair: nx.p.n, kind: nx.p.k, startApr: r1(apr(P.R(nx.p), nx.W)) } : null };
    });
    const cur = (s.allocs || []).filter((a) => a.weight >= 0.01 * s.amount).map((a) => {
      const p = P.byId.get(a.pool);
      return p ? row(p, a.weight, P.stakeFair({ allocs: [a] }), Math.round((100 * a.weight) / s.amount), { kept: keptA.includes(a) }) : null;
    }).filter(Boolean);
    if (away >= 0.01 * s.amount) cur.push(awayRow());
    const pick = options.find((x) => x.n === pickN) || options[0];
    return { best: pick.best, now: cur.sort(byPct), marketApr: r1(apr(P.Y, 1)), suggestedN: pickN, slack: r2(Math.max(POLICY.poolsSlack, POLICY.poolsPct * Math.max(...options.map((x) => x.usdPerDay || 0)))),
      options: options.length > 1 ? options : null };
  }

  // never allocated (or everything idle): no cooldown time, and nothing to wait for
  const neverAllocated = (s) => !s.cooldownEnd && (!(s.allocs || []).length || (s.chains || []).every((c) => !c.lastAllocated));

  // One lock. s = { id, name, amount, cooldownEnd, allocs: [{ pool, weight }], elsewhere }
  // (no earlier visit, so no standing suggestion and no "you moved")
  function adviseLock(s, P, X) {
    const { now, name, aero } = X;
    const big = s.amount >= BIG;
    const apr = (v, a) => (aero && a ? (v * 365 * 100) / (a * aero) : 0);
    // sAERO whose pools this site cannot read (a wallet's other networks) stays where it is and is counted at the
    // market's average pay per sAERO, in both the best split and staying; the split covers the rest.
    const away = Math.max(0, Math.min(s.amount, s.elsewhere || 0));
    const sA = away > 0 ? { ...s, amount: s.amount - away } : s;
    // Dollar figures (10-30: the estimates ran consistently low): valued with the picker's own crowding (the
    // current method, summary.crowd) times k = summary.estK (learn.json calib: what the picks really earned vs what was shown;
    // .big for 50k+ locks, .small below; 1 when absent or stale). Measured 10-30: the shown $ ran 30-75% BELOW what the picks
    // earned every day since launch week (incentive forecasts on target; fees ~40% above the 4-day average, pools filled less
    // than the crowding forecast). R x k leaves pool sizes and the split exactly as picked and scales every $ by k. Until
    // 10-30 the figures used exponent 0.65 for pools whose incentives started < 24 h ago (a launch-week setting, 10-26) while
    // the picks used the current method, so the page could contradict itself (a 9.5k lock: "All networks" picked an Optimism
    // pool shown at $2.65/day while "Base only" showed a different pool at $2.96/day).
    // sAERO on networks this site cannot read is counted at PD.Y (the market average x k), so it is scaled the same.
    const PD = planner(P.sum, { k: estKOf(P.sum, s.amount) });
    const fair = PD.stakeFair(s) + away * PD.Y, pageNow = P.stakePay(s) + away * P.Y;
    const G = gainKOf(P.sum, s.amount), sh = (v) => (v > fair ? fair + G * (v - fair) : v);   // a better split's $ as shown
    const NX = big ? X.nets : null;   // 11-08: a small lock is planned on Base only whatever the network setting
    const planOf = (drop, keep) => {
      const pools = P.poolsFor({ minSize: PLAN.minSize, baseOnly: PLAN.baseOnly, nets: NX, drop });
      const adv = P.advisedOption(sA, pools, { ns: POLICY.poolsN, slack: POLICY.poolsSlack, pct: POLICY.poolsPct, baseOnly: PLAN.baseOnly, nets: NX, keep, big: BIG, small: PLAN.maxPools });
      const valued = (q) => { const v = PD.splitValue(adv.sB, q.split.map((c) => ({ pool: c.p.id, x: c.x }))); return { split: q.split.map((c, j) => ({ ...c, pay: v[j].pay })), best: v.reduce((t, c) => t + c.pay, 0) }; };
      const opts = adv.opts.map((x) => ({ n: x.n, o: valued(x.o) })), o = opts.find((x) => x.n === adv.n).o;
      const keptPay = (adv.kept.length ? PD.stakeFair({ allocs: adv.kept }) : 0) + away * PD.Y, best = o.best + keptPay;
      const fee = moveFee(feeFrom(s, adv.kept), feeTo(o.split), P.sum.eth)?.usd || 0, extra47 = ((sh(best) - fair) * HOLD) / 86400;
      return { pools, adv, opts, o, keptPay, best, fee, net: extra47 - fee, extra47 };
    };
    // the move tests (worth below, with fees): netMix prefers the best-netting mix that passes them (same as server adviceMix)
    const mixOk = (x) => x.best >= fair * (1 + POLICY.moveRel) && x.best - fair >= POLICY.moveMin && x.fee <= x.extra47;
    // the networks to use: the mix that earns the most over the 47 h hold after its network fees (netMix). Found 11-04:
    // a small lock whose every-network best put a third on Ethereum (about $2.50 to enter) was told to stay, while a
    // Base split for about $0.10 clearly paid.
    // 11-08: a lock under 50k is planned on Base only and leaves other networks (the same rule as the server's adviceMix)
    const C = !big ? planOf([...new Set(P.sum.pools.map((p) => p.c))].filter((c) => c && c !== "base"), [])
      : netMix(planOf, [...new Set((s.allocs || []).map((a) => String(a.pool).split(":")[0]))], mixOk);
    const { pools, adv, opts, o, keptPay } = C;
    const sB = adv.sB, keptA = adv.kept, keptAmt = adv.keptAmt + away, pickN = adv.n;
    const keptWhy = keptAmt > 0 ? `${Math.round((100 * keptAmt) / s.amount)}% stays on ${keptA.length ? list([...new Set(keptA.map((a) => cap(String(a.pool).split(":")[0])))]) : "other networks"} (counted${away ? " at the market average: its network could not be read just now" : ""}).` : null;
    const oBest = C.best;
    const freshRows = o.split.map((c) => ({ pool: c.p.id, x: c.x, pay: c.pay }));
    const freshPct = wholePct(freshRows.map((c) => c.x), s.amount, Math.round((100 * sB.amount) / s.amount));
    const cdEnd = s.cooldownEnd || null, free = cdEnd ? cdEnd <= now : neverAllocated(s);
    // network fees for moving to a split (moveFee): leaving every network it is on now, entering the split's
    const feeFor = (rows) => moveFee(feeFrom(s, keptA), feeTo(rows), P.sum.eth);
    // Fee hurdle (11-02): a split is not
    // a move when its network fees are more than the extra it earns (as shown) over the 47 h hold. A standing split keeps
    // its place while the extra covers 80% of the fees, so a few cents either way does not flip the advice every run.
    const feeOf = (to) => moveFee(feeFrom(s, keptA), to, P.sum.eth)?.usd || 0;   // to = moveFee entries { c, x, pool }
    const extra47 = (best) => ((sh(best) - fair) * HOLD) / 86400;
    const feeOk = (best, chains, slack = 1) => feeOf(chains) <= extra47(best) * slack;
    const bestChains = feeTo(o.split);

    const e = { lock: s.id == null ? null : String(s.id), name: s.name, amount: Math.round(s.amount), big, cooldownEnd: cdEnd, free,
      nowUsdPerDay: r2(fair), nowApr: r1(apr(fair, s.amount)), pageNowUsdPerDay: r2(pageNow),
      bestUsdPerDay: r2(sh(oBest)), bestApr: r1(apr(sh(oBest), s.amount)), gain: r2(sh(oBest) - fair), gainPct: fair > 0 ? r1((sh(oBest) / fair - 1) * 100) : null,
      gainModel: r2(oBest - fair), gainPctModel: fair > 0 ? r1((oBest / fair - 1) * 100) : null, gainK: G,
      split: [], why: [], until: null, ending: null, preview: null, wouldMove: false, moveFee: null,
      poolsN: pickN, explain: explainLock(PD, s, sB, pools, opts, pickN, keptA, now, apr, away) };
    // the panel's pool-count options and rows, shown the same way (usdModel = the raw figure, for "worth a move")
    if (G < 1 && e.explain) {
      const X = e.explain, done = new Set();
      const scale = (rows, from) => { const to = sh(from), f = from > 0 ? to / from : 1; if (f !== 1 && !done.has(rows)) for (const r of rows || []) { r.usdPerDay = r2(r.usdPerDay * f); r.aprPct = r1(r.aprPct * f); } done.add(rows); return to; };
      for (const op of X.options || []) { const to = scale(op.best, op.usdPerDay); op.usdModel = op.usdPerDay; op.usdPerDay = r2(to); op.aprPct = r1(apr(to, s.amount)); }
