    }
    const worth = (best, base, chains) => best >= base * (1 + POLICY.moveRel) && best - base >= POLICY.moveMin && (!chains || feeOk(best, chains));
    const feeBlocked = () => worth(oBest, fair) && !feeOk(oBest, bestChains);   // the % and $ tests pass; only the fees say no
    const fairWhy = () => (Math.abs(pageNow - fair) >= 0.05 * Math.max(fair, 0.01) && big
      ? `Where it is: ${usd(fair)}/day over the next 47 h after the crowd moves in (${usd(pageNow)}/day at today's sizes).` : null);
    let state;

    if (!free) {
      state = "on-cooldown";
      e.until = cdEnd;
      if (cdEnd - now <= POLICY.preview) {
        const go = worth(oBest, fair, bestChains);
        if (go) e.why.push(keptWhy);
        e.why.push(fairWhy());
        e.preview = go ? splitOut(P, name, s, freshRows, freshPct, apr) : null;
        e.moveFee = go ? feeFor(e.preview) : null;
        e.wouldMove = go;
      }
    } else {
      e.until = now + 600;
      if (worth(oBest, fair, bestChains)) {
        state = "move-now";
        e.split = splitOut(P, name, s, freshRows, freshPct, apr);
        e.moveFee = feeFor(e.split);
        const end = endingOf(PD, freshRows, now);
        if (end) e.ending = end;
        e.why.push(keptWhy);
        if (end && end.share >= 0.5 && end.at) e.why.push(end.at > now + HOLD
          ? `${pctTxt(end.share)} of this pay is incentives that end ${when(end.at, now)}. Plan to move again between ${when(now + HOLD, now)} and then.`
          : `${pctTxt(end.share)} of this pay is incentives that end ${when(end.at, now)}, inside the hold; the figures count only the hours they still pay.`);
        e.why.push(fairWhy());
        if (big && e.why.filter(Boolean).length < 4) e.why.push("Why not wait for new incentives: at this size it tested as a wash or a loss (new programs fill up within hours), while every hour in a weaker split costs money.");
      } else {
        state = "stay";
        const rel = oBest / Math.max(fair, 1e-9) - 1, fb = feeBlocked();
        e.why.push(fb ? `A move would earn about ${usd(extra47(oBest))} more over the 47 h hold, less than the network fees to get there (about ${usd(feeOf(bestChains))}); this page re-checks every 10 minutes and will say Move now when the extra covers them.`
          : `It stays free, so this page re-checks every 10 minutes and will say Move now as soon as something is at least 3% better${big ? "" : " and $0.25/day more"}.`);
        e.why.push(fairWhy());
        if (!big && !fb && rel >= POLICY.moveRel) e.why.push(`The best split is ${pctTxt(sh(oBest) / Math.max(fair, 1e-9) - 1)} better but adds only ${usd(sh(oBest) - fair)}/day, not worth a transaction.`);
      }
    }
    e.why = e.why.filter(Boolean).slice(0, 4);
    e.state = state;
    const moveRows = state === "move-now" ? e.split : e.wouldMove ? e.preview : [];
    return { e, moves: moveRows.length > 0, rows: moveRows.map((c) => ({ pool: c.pool, x: c.sAERO })), sPlan: sB };
  }

  // the summary after lock s leaves its pools and joins `rows` ([{ pool, x }])
  function shifted(sum, s, rows) {
    const d = new Map();
    for (const a of s.allocs || []) d.set(a.pool, (d.get(a.pool) || 0) - a.weight);
    for (const c of rows) d.set(c.pool, (d.get(c.pool) || 0) + c.x);
    return { ...sum, pools: sum.pools.map((p) => (d.has(p.id) ? { ...p, W: Math.max(0, p.W + d.get(p.id)) } : p)) };
  }

  // ---------- "Coming up", from the public calendar (calendar.json) and the visitor's locks ----------
  // cat: "locks" (these locks), "cool" (sAERO off cooldown), "inc" (incentives), "stocks", "whale". `top` marks the
  // lines the All tab shows (most important first, at most one whale/crowd/stock line each, 6 lines).
  // pairs = [{ s: the lock, e: its advice entry }]
  function nextThings(cal, pairs, sum, now) {
    const out = [];
    const byId = new Map((sum.pools || []).map((p) => [p.id, p]));
    const bigPairs = pairs.filter((x) => x.e.big);
    const watch = bigPairs.length ? bigPairs : pairs;   // a visitor with small locks only: those locks
    const inUse = new Set(pairs.flatMap((x) => (x.s.allocs || []).map((a) => a.pool)));
    for (const v of cal?.events || []) {
      if (v.at < now - 600 && !(v.until > now)) continue;
      if (v.kind === "queued_batch") out.push({ prio: 0, cat: "inc", at: v.at, until: v.until, kind: v.kind, text: `New incentives are being signed: ${v.nPools} pools, ${usd(v.usdPerDay || 0)}/day.`, short: `New incentives being signed: ${v.nPools} pools, ${usd(v.usdPerDay || 0)}/day` });
