          if (loses >= Math.max(1, 0.2 * (e.nowUsdPerDay || 0))) cur.push({ e, loses });
        }
        if (cur.length) out.push({ prio: 2, cat: "inc", at: v.at, kind: v.kind, text: `Incentives stop on ${v.nPools} pool${v.nPools === 1 ? "" : "s"} (${usd(v.usdPerDay)}/day). ${cap(cur.map((h) => `${h.e.name} earns about ${usd(h.loses)}/day of its ${usd(h.e.nowUsdPerDay)}/day from them`).join("; "))}.`,
          short: `Incentives end (${v.nPools} pools): ${cur.map((h) => `${h.e.name} −${usd(h.loses)}/day`).join(", ")} if they stay put` });
        else if (v.usdPerDay >= 1000) out.push({ prio: 6, cat: "inc", at: v.at, kind: v.kind, text: `Incentives of ${usd(v.usdPerDay)}/day stop on ${v.nPools} pool${v.nPools === 1 ? "" : "s"}${pairs.length ? " (my locks are not in them)" : ""}.`, short: `${usd(v.usdPerDay)}/day of incentives end (${v.nPools} pool${v.nPools === 1 ? "" : "s"}${pairs.length ? ", not in my locks" : ""})` });
      } else if (v.kind === "maybe_batch" && (v.confidence || 0) >= 0.2)
        out.push({ prio: 3, cat: "inc", at: v.at, until: v.until, kind: v.kind,
          // "likely" only at 60%+
          short: `${v.confidence >= 0.6 ? "New incentives likely" : v.confidence >= 0.25 ? "Aero team may add incentives" : "New incentives unlikely"} (${pctTxt(v.confidence)})`,
          text: v.samples && v.recentN
            ? `The Aero team's ${usd(v.usdPerDay)}/day batch on ${v.batchPools} pools ends ${when(v.batchEnd, now)}. When the team adds incentives, ${pctTxt(v.inWin / v.samples)} of the time it is in this window (${v.inWin} of ${v.samples} weeks since Apr 2024); it added some in ${v.recentK} of the last ${v.recentN} weeks (${pctTxt(v.chanceOfAnyRenewal)}). ${pctTxt(v.chanceOfAnyRenewal)} × ${pctTxt(v.inWin / v.samples)} ≈ ${pctTxt(v.confidence)}.${v.leadH ? ` Last time it renewed ${v.leadH} h before the old batch ended.` : ""} The advice doesn't wait for it.`
            : `${v.what ? cap(v.what) + ". " : ""}About ${pctTxt(v.confidence)}. The advice doesn't wait for it.` });
      else if (v.kind === "crowd" && v.until && !(v.pools || []).length && v.at - now < 72 * H) {
        if ((v.freedM || 0) >= 30) out.push({ prio: v.at - now < 24 * H ? 4 : 9, cat: "cool", at: v.at, until: v.until, kind: v.kind, text: `${v.freedM}M sAERO comes off cooldown; about ${v.expectedM}M is expected to move, often into the best-paying pools.`, short: `${v.freedM}M sAERO frees up; ~${v.expectedM}M likely to move` });
      } else if (v.kind === "whale" && (v.pools || []).some((p) => inUse.has(p.id))) {
        const there = v.pools.filter((p) => inUse.has(p.id));
        out.push({ prio: 5, cat: "whale", at: v.at, kind: v.kind, text: `The Aero team/protocol wallet (about half of all sAERO) is free and has never moved; it holds ${list(there.slice(0, 2).map((p) => `${Math.round(100 * (p.share || 0))}% of ${String(p.n).replace(/ (CL\d+|vAMM|sAMM)$/, "")}`))}, where these locks are.`, short: "Team/protocol wallet (half of all sAERO) is free; it sits in these locks' pools" });
      } else if (v.kind === "inc_launch" && v.what)
        out.push({ prio: 2, cat: "inc", at: v.at, until: v.until, kind: v.kind, text: cap(v.what) + ".", short: v.short || cap(v.what) });
      else if (v.kind === "inc_start" && (v.usdPerDay || 0) >= 500)
        out.push({ prio: 8, cat: "inc", at: v.at, kind: v.kind, text: v.what ? cap(v.what) + "." : `Incentives of ${usd(v.usdPerDay)}/day start on ${v.nPools} pools.`, short: `Incentives start: ${usd(v.usdPerDay)}/day on ${v.nPools} pool${v.nPools === 1 ? "" : "s"}` });
      else if (v.kind === "whale")
        out.push({ prio: 10, cat: "whale", at: v.at, kind: v.kind, text: `${v.what || "The Aero team/protocol wallet (about half of all sAERO) can move."}`, short: "Team/protocol wallet (half of all sAERO) is free to move" });
      else if (v.kind === "market_open" || v.kind === "market_close" || v.kind === "weekend")
        out.push({ prio: 11, cat: "stocks", at: v.at, until: v.until, kind: v.kind, text: v.what ? cap(v.what) + "." : v.kind,
          short: v.kind === "market_open" ? `US market open: stock-token fees pick up${v.usdPerDay ? ` (+${usd(v.usdPerDay)}/day)` : ""}` : v.kind === "market_close" ? "US market closes: stock-token fees slow" : "Weekend: stock markets shut (stock-token fees lower)" });
    }
    // a lock that frees later: when it can move
    for (const { e } of watch) if (e.cooldownEnd && e.cooldownEnd > now + 600) out.push({ prio: 7, cat: "locks", at: e.cooldownEnd, kind: "lock_free", text: `${e.name} can move.`, short: `${e.name} can move` });
    // All tab: most important first, at most one whale/crowd/stock line each, 6 lines; the other tabs show every line of
    // their kind (up to 30 in all), in time order
    const seen = new Set(), top = new Set();
    out.sort((a, b) => a.prio - b.prio || a.at - b.at).filter((x) => { const k = ["crowd", "whale", "maybe_batch"].includes(x.kind) || x.cat === "stocks" ? x.cat + x.kind : x.kind + x.at + x.text; if (seen.has(k)) return false; seen.add(k); return true; })
      .slice(0, 6).forEach((x) => top.add(x));
    const dup = new Set();
    return out.filter((x) => { const k = x.kind + x.at + x.short; if (dup.has(k)) return false; dup.add(k); return true; })
      .sort((a, b) => a.at - b.at).slice(0, 30).map(({ prio, ...x }) => ({ ...x, top: top.has(out.find((y) => y.kind === x.kind && y.at === x.at && y.short === x.short)) || undefined }));
  }

  // ---------- all locks ----------
  // locks = [{ id|null, name, amount, cooldownEnd, allocs, elsewhere }], cal = calendar.json, now = unix seconds,
  // nets = the networks to suggest pools on (null = all); sAERO already on another network stays where it is
  function advise({ sum, locks = [], cal = null, now = Date.now() / 1000, nets = null }) {
    const P0 = planner(sum);
    const X = { now, name: namer(sum), aero: sum.aero, nets };
    const mine = locks.filter((s) => s.amount > 0).map((s, i) => ({ ...s, _i: i })).sort((a, b) => b.amount - a.amount);
    const res = new Map();
    // big locks free now or within the preview window, in order of free time (locks freeing within an hour of each
    // other form one group, biggest first), each planned with the earlier ones' new splits (or previews) counted
    let sumK = sum;
    const freeAt = (s) => Math.max(now, s.cooldownEnd || now);
    const ahead = mine.filter((s) => s.amount >= BIG && (s.cooldownEnd ? s.cooldownEnd <= now + POLICY.preview : neverAllocated(s))).sort((a, b) => freeAt(a) - freeAt(b));
    const grp = new Map(); let g0 = -Infinity, gi = -1;
    for (const s of ahead) { if (freeAt(s) - g0 > POLICY.together) { g0 = freeAt(s); gi++; } grp.set(s._i, gi); }
    ahead.sort((a, b) => grp.get(a._i) - grp.get(b._i) || b.amount - a.amount);
    for (const s of ahead) {
      const r = adviseLock(s, sumK === sum ? P0 : planner(sumK), X);
      res.set(s._i, r);
      if (r.moves && r.rows.length) sumK = shifted(sumK, r.sPlan, r.rows);
    }
    for (const s of mine) if (!res.has(s._i)) res.set(s._i, adviseLock(s, P0, X));
    // "if you stay" for the locks together: every lock valued on the same, unshifted pools (nowUsdPerDay of a lock planned
    // after another one counts that one as already moved), the lock's own estimate scale, other networks at the average
    for (const s of mine) {
      const Pk = planner(sum, { k: estKOf(sum, s.amount) }), away = Math.max(0, Math.min(s.amount, s.elsewhere || 0));
      res.get(s._i).e.stayUsdPerDay = r2(Pk.stakeFair(s) + away * Pk.Y);
    }
    const entries = mine.map((s) => res.get(s._i).e);
    return { at: now, dataAt: sum.at, aero: sum.aero, P: P0, Y: P0.Y,
      locks: entries.filter((e) => e.big).concat(entries.filter((e) => !e.big)),
      next: nextThings(cal, mine.map((s) => ({ s, e: res.get(s._i).e })), sum, now) };
  }

  // estKOf / gainKOf / wholePct also serve the page's Plan tab (every lock moved at once), so it scales its $ exactly as the advice does
  const api = { planner, advise, moveFee, netMix, when, neverAllocated, isStockSym, POLICY, PLAN, estKOf, gainKOf, wholePct };   // netMix: for the plan check
  root.SaeroPlan = api;
  if (typeof module !== "undefined" && module.exports) module.exports = api;
})(typeof window !== "undefined" ? window : globalThis);
